import 'server-only';
import { cookies, headers } from 'next/headers';
import { and, eq, lt, sql } from 'drizzle-orm';
import { getDb } from '@/db';
import { sessions } from '@/db/schema';
import { sessionCookieSecure } from './cookie-policy';
import { forwardedAddress } from '@/lib/auth/audit';

export const SESSION_COOKIE = 'aktivacity_session';
const SESSION_TTL_MS = 12 * 60 * 60 * 1000; // one working day

/**
 * The cookie carries the session row's UUID, generated by Postgres with a
 * CSPRNG (122 bits). Note the tradeoff: anyone able to SELECT from `sessions`
 * could impersonate a user, so database access stays limited to the app role.
 */
export async function createSession(userId: number): Promise<void> {
  const db = getDb();
  const expiresAt = new Date(Date.now() + SESSION_TTL_MS);

  const headerList = await headers();
  // The same rule the activity log applies: a hop the inet column would
  // refuse must not refuse the login.
  const ipAddress = forwardedAddress(headerList.get('x-forwarded-for'));

  const [row] = await db
    .insert(sessions)
    .values({
      userId,
      expiresAt,
      ipAddress,
      userAgent: headerList.get('user-agent')?.slice(0, 500) ?? null,
    })
    .returning({ id: sessions.id });

  const cookieStore = await cookies();
  cookieStore.set(SESSION_COOKIE, row.id, {
    httpOnly: true,
    // Secure over HTTPS (Caddy); a plain-HTTP install on the office network
    // still gets a cookie the browser keeps. See ./cookie-policy.
    secure: sessionCookieSecure(headerList.get('x-forwarded-proto')),
    sameSite: 'lax',
    path: '/',
    expires: expiresAt,
  });
}

export async function destroySession(): Promise<void> {
  const cookieStore = await cookies();
  const token = cookieStore.get(SESSION_COOKIE)?.value;

  if (token && isUuid(token)) {
    await getDb().delete(sessions).where(eq(sessions.id, token));
  }
  cookieStore.delete(SESSION_COOKIE);
}

/** Ends every session for a user — used when deactivating or demoting them. */
export async function destroyAllSessionsFor(userId: number): Promise<void> {
  await getDb().delete(sessions).where(eq(sessions.userId, userId));
}

export async function readSessionToken(): Promise<string | null> {
  const token = (await cookies()).get(SESSION_COOKIE)?.value;
  return token && isUuid(token) ? token : null;
}

/** Opportunistic cleanup; also worth running from a scheduled job later. */
export async function purgeExpiredSessions(): Promise<number> {
  const result = await getDb()
    .delete(sessions)
    .where(and(lt(sessions.expiresAt, sql`now()`)))
    .returning({ id: sessions.id });
  return result.length;
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
function isUuid(value: string): boolean {
  return UUID_RE.test(value);
}
